const { app, BrowserWindow } = require('electron');
app.setName('PI Settings Extensions Fixture');
app.whenReady().then(async () => {
  const window = new BrowserWindow({ show: false, width: 1120, height: 780, webPreferences: { sandbox: true, contextIsolation: true, nodeIntegration: false, backgroundThrottling: false } });
  const evaluate = source => window.webContents.executeJavaScript(source);
  const until = expression => evaluate(`new Promise((resolve, reject) => {
    const start = performance.now(); function check() { try { if (${expression}) return resolve(true); } catch(error) { return reject(error); }
      if (performance.now() - start > 5000) return reject(new Error('Timed out: ' + ${JSON.stringify(expression)} + '\\n' + document.body.innerText)); requestAnimationFrame(check); } check(); })`);
  const check = async (name, expression) => { if (!await evaluate(expression)) throw new Error('FAIL ' + name); console.log('PASS ' + name); };
  const click = selector => evaluate(`document.querySelector(${JSON.stringify(selector)}).click()`);
  const input = (selector, value) => evaluate(`(() => { const node = document.querySelector(${JSON.stringify(selector)}); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(node, ${JSON.stringify(value)}); node.dispatchEvent(new Event('input', { bubbles: true })); })()`);
  let loaded = false;
  const open = async query => { if (loaded) await check('no unexpected fixture IPC', 'window.extensionsFixture.unexpected.length === 0'); await window.loadURL(process.env.PI_SETTINGS_EXTENSIONS_FIXTURE_URL + query); await until('!!window.extensionsFixture'); loaded = true; };
  try {
    await open('');
    await input('input[type="range"]', '12');
    await until('document.querySelector("output").textContent === "12px"');
    await evaluate('window.extensionsFixture.deferBlur(true)');
    await click('.plugin-scenic-blur-actions button');
    await until('window.extensionsFixture.requests.length === 1');
    await click('.plugin-scenic-theme-card:nth-child(2)');
    await until('document.querySelector("output").textContent === "3px"');
    await evaluate('window.extensionsFixture.settleBlur()');
    await until('window.extensionsFixture.blurSettled() === 1');
    await check('late Apply cannot dirty another theme', 'document.querySelector(".plugin-scenic-blur-actions button").disabled && document.querySelector("output").textContent === "3px"');
    await evaluate('window.extensionsFixture.deferBlur(false)');
    await input('input[type="range"]', '8');
    await until('document.querySelector("output").textContent === "8px"');
    await click('.plugin-scenic-blur-actions button');
    await until('window.extensionsFixture.blurSettled() === 2 && document.querySelector(".plugin-scenic-blur-actions button").disabled');
    await check('blur Apply persists the selected theme and value', 'window.extensionsFixture.requests[1].input.themeId === "fixture.b" && window.extensionsFixture.requests[1].input.blur === 8');
    await input('input[type="range"]', '10');
    await until('document.querySelector("output").textContent === "10px"');
    await evaluate('window.extensionsFixture.failBlur(true)');
    await click('.plugin-scenic-blur-actions button');
    await until('window.extensionsFixture.toasts.some(([message]) => message === "Injected blur failure")');
    await check('failed blur Apply preserves draft for retry', 'document.querySelector("output").textContent === "10px" && !document.querySelector(".plugin-scenic-blur-actions button").disabled');

    await open('?page=remote&remoteError');
    await until('!!document.querySelector(".settings-remote-host-error")');
    await evaluate('window.extensionsFixture.failRemote(false)');
    await click('.settings-remote-host-error button');
    await until('!document.querySelector(".settings-remote-host-error") && document.querySelector(".settings-remote-host-list").getAttribute("aria-busy") === "false"');
    await check('remote inventory load error retries to a real empty state', 'document.querySelector(".settings-remote-host-list").textContent.includes(window.extensionsFixture.label("settings.remoteHosts.empty"))');
    await input('#remote-host-add-panel-ssh input', 'SSH draft');
    const field = async (panel, key) => panel + ' input[aria-label=' + JSON.stringify(await evaluate('window.extensionsFixture.label(' + JSON.stringify(key) + ')')) + ']';
    await input(await field('#remote-host-add-panel-ssh', 'settings.remoteHosts.sshHost'), 'fixture-host');
    await click('#remote-host-add-pair');
    await until('!document.querySelector("#remote-host-add-panel-pair").hidden');
    await input(await field('#remote-host-add-panel-pair', 'settings.remoteHosts.fieldLabel'), 'Pair draft');
    await input(await field('#remote-host-add-panel-pair', 'settings.remoteHosts.fieldUrl'), 'ws://fixture.invalid/v1/racp/ws');
    await input(await field('#remote-host-add-panel-pair', 'settings.remoteHosts.fieldPairingToken'), 'fixture-pair-token');
    await click('#remote-host-add-ssh');
    await until('!document.querySelector("#remote-host-add-panel-ssh").hidden');
    await check('SSH draft survives switching add modes', 'document.querySelector("#remote-host-add-panel-ssh input").value === "SSH draft"');
    await click('#remote-host-add-pair');
    await until('!document.querySelector("#remote-host-add-panel-pair").hidden');
    await click('#remote-host-add-panel-pair button[type="submit"]');
    await until('!!document.querySelector(".settings-remote-host-card")');
    await check('pairing creates inventory row and retains the other draft', 'document.querySelector(".settings-remote-host-name").textContent === "Pair draft" && document.querySelector("#remote-host-add-panel-ssh input").value === "SSH draft"');
    await evaluate('window.extensionsFixture.failRemote(true)');
    await click('.settings-remote-host-card-actions button');
    await until('!!document.querySelector(".settings-remote-host-error")');
    await check('inventory refresh failure retains the known inventory', '!!document.querySelector(".settings-remote-host-card")');
    await evaluate('window.extensionsFixture.failRemote(false)');
    await click('.settings-remote-host-error button');
    await until('!document.querySelector(".settings-remote-host-error") && !document.querySelector(".settings-remote-host-card")');

    await open('?page=sync&syncLoadError');
    await until('!!document.querySelector(".settings-config-sync-error-actions button")');
    await input(await field('', 'settings.configSync.endpoint'), 'https://draft.invalid/dav');
    await evaluate('window.extensionsFixture.failSyncLoad(false)');
    await click('.settings-config-sync-error-actions button');
    await until('!document.querySelector(".settings-config-sync-error-actions") && document.querySelector(".settings-config-sync").getAttribute("aria-busy") !== "true"');
    await check('sync state retry keeps the connection draft', 'document.querySelector("input[autocomplete=url]").value === "https://draft.invalid/dav"');
    await open('?page=sync');
    await until('document.querySelector(".settings-config-sync").getAttribute("aria-busy") !== "true"');
    await check('unconfigured sync starts with the connection form', 'document.querySelector(".settings-card-heading").textContent === window.extensionsFixture.label("settings.configSync.connectionTitle")');
    await input(await field('', 'settings.configSync.endpoint'), 'https://fixture.invalid/dav');
    await input(await field('', 'settings.configSync.appPassword'), 'fixture-app-password');
    await input(await field('', 'settings.configSync.backupPassword'), 'fixture-vault-password');
    await evaluate('window.extensionsFixture.deferSync(true)');
    const buttonByKey = key => evaluate('(() => { const button = [...document.querySelectorAll("button")].find(node => node.textContent.trim() === window.extensionsFixture.label(' + JSON.stringify(key) + ')); if (!button || button.disabled) throw new Error("Missing or disabled action"); button.click(); })()');
    await buttonByKey('settings.configSync.enable');
    await until('window.extensionsFixture.state().configured && window.extensionsFixture.requests.some(entry => entry.channel.endsWith("/syncNow"))');
    await evaluate('window.extensionsFixture.progress({ phase: "upload", completedObjects: 1, totalObjects: 2 })');
    await until('!!document.querySelector(".settings-config-sync-progress")');
    await check('configured sync leads with status, then manual progress and scope', 'document.querySelector(".settings-card-heading").textContent === window.extensionsFixture.label("settings.configSync.statusTitle") && document.querySelector(".settings-config-sync-progress").previousElementSibling.textContent.includes(window.extensionsFixture.label("settings.configSync.statusTitle"))');
    await check('saving connection clears passwords before first sync completes', '[...document.querySelectorAll("input[type=password]")].every(input => input.value === "") && window.extensionsFixture.toasts.some(([message]) => message === window.extensionsFixture.label("settings.configSync.configured"))');
    await evaluate('window.extensionsFixture.failSync(true); window.extensionsFixture.settleSync()');
    await until('!document.querySelector(".settings-config-sync-progress") && document.querySelector(".settings-config-sync-error-actions")');
    await check('sync failure keeps configured state and saved feedback distinct', 'window.extensionsFixture.state().configured && document.querySelector(".settings-card-heading").textContent === window.extensionsFixture.label("settings.configSync.statusTitle")');
    await check('sensitive categories remain opt-out', '!window.extensionsFixture.state().includeSecrets && !window.extensionsFixture.state().includeMemory');
    await open('?page=sync&configured&approvals');
    await until('!!document.querySelector(".settings-config-sync-approval")');
    await check('pending approval precedes sync scope and connection', '(() => { const titles = [...document.querySelectorAll(".settings-card-heading")].map(node => node.textContent); return titles.indexOf(window.extensionsFixture.label("settings.configSync.approvalsTitle")) < titles.indexOf(window.extensionsFixture.label("settings.configSync.categoriesTitle")) && titles.indexOf(window.extensionsFixture.label("settings.configSync.categoriesTitle")) < titles.indexOf(window.extensionsFixture.label("settings.configSync.connectionTitle")); })()');
    await buttonByKey('settings.configSync.approve');
    await until('!document.querySelector(".settings-config-sync-approval")');
    await check('approval preserves host digest contract', 'window.extensionsFixture.requests.some(entry => entry.input?.approvalId === "fixture-approval" && entry.input?.digest === "fixture-digest")');
    await open('?page=sync&configured&locked');
    await until('!!document.querySelector(".settings-config-sync-password-actions input")');
    await check('locked sync keeps unlock password beside its action', 'document.querySelector(".settings-config-sync-password-actions").closest(".settings-card-block") === document.querySelector(".settings-card-block")');
    await input('.settings-config-sync-password-actions input', 'fixture-unlock-password');
    await buttonByKey('settings.configSync.unlock');
    await until('!window.extensionsFixture.state().locked && !document.querySelector(".settings-config-sync-password-actions input")?.value');
    await check('unlock preserves the host boundary and clears its secret', 'window.extensionsFixture.requests.some(entry => entry.channel.endsWith("/unlock") && entry.input.backupPassword === "fixture-unlock-password")');
    await check('no unexpected fixture IPC', 'window.extensionsFixture.unexpected.length === 0');
    console.log('SETTINGS_EXTENSIONS_PATHS_PASS');
    app.exit(0);
  } catch (error) { console.error(error); app.exit(1); }
});
